def _query_pairs(query):
    """
    Yield (key, value) pairs for a reverse() ``query`` argument in the
    iteration order of the supplied container.

    Scalar values -- strings (including lazy string proxies), bytes and
    numbers -- are yielded untouched so that urllib's urlencode semantics are
    preserved. Values nested inside lists, tuples, sets or other non-scalar
    iterables are expanded into repeated keys at every nesting level, so a
    container can never leak into the URL through its repr(). Mappings are not
    iterated as values because their key ordering is unrelated to the query
    order; pass sequences of (key, value) pairs instead.
    """

    def expand(value):
        # str/bytes cover lazy string proxies as well, since they concatenate
        # and quote like plain strings.
        if isinstance(value, (str, bytes)):
            yield value
        elif isinstance(value, Mapping):
            yield value
        elif isinstance(value, Iterable):
            for item in value:
                yield from expand(item)
        else:
            yield value

    if isinstance(query, QueryDict):
        for key, values in query.lists():
            for value in values:
                yield key, value
    elif isinstance(query, Mapping):
        for key, value in query.items():
            for leaf in expand(value):
                yield key, leaf
    else:
        try:
            items = list(query)
        except TypeError as err:
            raise TypeError(
                "not a valid non-string sequence or mapping object"
            ) from err
        for item in items:
            try:
                key, value = item
            except (TypeError, ValueError) as err:
                raise TypeError(
                    "not a valid non-string sequence or mapping object"
                ) from err
            for leaf in expand(value):
                yield key, leaf


def _append_query_fragment(url, query=None, fragment=None):
    """
    Append an encoded query string and/or fragment identifier to a reversed
    URL. The query string, when present, follows the path; the fragment always
    comes last. Neither separator is added for an empty value, and separators
    already present in the reversed path are not duplicated.
    """
    scheme, netloc, path, existing_query, existing_fragment = urlsplit(url)
    if query is not None:
        query_string = query.urlencode() if isinstance(query, QueryDict) else None
        if query_string is None:
            pairs = list(_query_pairs(query))
            if pairs:
                query_string = urlencode(pairs, doseq=True)
        if query_string:
            existing_query = (
                f"{existing_query}&{query_string}" if existing_query else query_string
            )
    if fragment is not None:
        # Validate the type explicitly so the public TypeError contract is
        # honoured regardless of how the final URL is assembled; str (and its
        # lazy proxies, which behave like str when concatenated) is the only
        # accepted type.
        if not isinstance(fragment, str) and not hasattr(fragment, "__radd__"):
            raise TypeError(
                "fragment must be a string, not %s" % type(fragment).__name__
            )
        existing_fragment = str(fragment) if existing_fragment is None else fragment
    return urlunsplit((scheme, netloc, path, existing_query, existing_fragment))


